#!/usr/bin/env node
'use strict';
/**
 * tools/beta/og.js — per-page 1200×630 share cards (B-36, ROUND-1 gap #9; RFC §6.5). Platform-owned.
 *
 *   node tools/beta/og.js            # render beta/assets/og/<fileKey>.png for every place page + country-<key>.png
 *   node tools/beta/og.js tokyo      # just these page keys (or country-<key>)
 *   (npm run beta:og from tools/, then npm run beta so og:image points at the new files)
 *
 * Inputs (read only, all generated by `npm run beta`): beta/data/places/*.json, beta/data/guide.json,
 * beta/assets/tokens.css, beta/assets/fonts/*.woff2, data/countries.json. Output: PNG under beta/assets/og/.
 * The card is typographic + map art only — no photos — built from the design tokens (the city's own skin) and
 * a scatter of the page's VERIFIED pins (lib/art.js; no OSM geometry, so no map credit is needed). Every number
 * on it is computed (stats); the ★ line is the build-time signature (lib/guide.js).
 *
 * Kept out of `npm run beta` on purpose (RFC §3.3): it needs Chromium, and PNG bytes are not reproducible across
 * renderers. build.js only READS these files; a missing card falls back to the shared assets/og-cover.png.
 */
const fs = require('fs');
const path = require('path');
const art = require('./lib/art');

const ROOT = path.resolve(__dirname, '..', '..');
const BETA = path.join(ROOT, 'beta');
const OUT = path.join(BETA, 'assets', 'og');
const rd = p => fs.readFileSync(path.join(ROOT, p), 'utf8');
const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
const fmt = n => Number(n).toLocaleString('en-US');

function loadPlaywright() {
  for (const t of ['playwright', '/opt/node22/lib/node_modules/playwright', '/opt/node-tools/node_modules/playwright']) {
    try { return require(t); } catch (e) { /* next */ }
  }
  return null;
}

const font = (fam, file, style) => `@font-face{font-family:"${fam}";font-style:${style};font-weight:400 900;src:url(data:font/woff2;base64,${fs.readFileSync(path.join(BETA, 'assets/fonts', file)).toString('base64')}) format("woff2")}`;
// W6 (design/beta/style/DECISION.md): Playfair (display) + Inter (UI), every script subset make-fonts.py ships.
const FONTS = fs.readdirSync(path.join(BETA, 'assets/fonts')).filter(f => /^(playfair|inter)-(normal|italic)-.+\.woff2$/.test(f)).sort()
  .map(f => { const [fam, style] = f.split('-'); return font(fam === 'inter' ? 'Inter' : 'Playfair', f, style); }).join('');
const TOKENS = rd('beta/assets/tokens.css');

const CSS = `
*{box-sizing:border-box;margin:0;padding:0}
html,body{width:1200px;height:630px;overflow:hidden}
body{background:var(--paper);color:var(--ink);font-family:var(--font-ui)}
.card{position:relative;display:grid;grid-template-columns:690px 510px;width:1200px;height:630px}
.l{padding:56px 40px 48px 64px;display:flex;flex-direction:column;border-left:14px solid var(--city)}
.brand{font-family:var(--font-display);font-style:italic;font-size:30px;letter-spacing:.01em;color:var(--ink)}
.brand b{font-style:normal;color:var(--city);margin-right:8px}
.brand span{font-family:var(--font-ui);font-style:normal;font-size:17px;color:var(--ink-3);margin-left:10px;letter-spacing:.02em}
.eyebrow{margin-top:44px;font-size:20px;color:var(--city-ink);letter-spacing:.04em}
h1{font-family:var(--font-display);font-weight:500;font-size:var(--h1,92px);line-height:1.0;margin-top:10px;letter-spacing:-.01em}
.nat{font-family:var(--font-native);font-size:36px;color:var(--city-ink);margin-top:12px}
.sig{margin-top:auto;font-family:var(--font-display);font-style:italic;font-size:30px;line-height:1.2;color:var(--ink)}
.sig b{font-style:normal;font-family:var(--font-ui);font-weight:600;font-size:17px;letter-spacing:.06em;color:var(--city-ink);display:block;margin-bottom:6px}
.facts{margin-top:22px;font-size:20px;line-height:1.45;color:var(--ink-2)}
.facts strong{color:var(--ink);font-weight:600}
.r{position:relative;background:var(--city-wash);display:flex;align-items:center;justify-content:center;overflow:hidden}
.r::before{content:"";position:absolute;inset:0;background:var(--motif-ink);opacity:.9}
.r svg{position:relative;width:470px;height:auto;max-height:520px}
.cap{position:absolute;left:24px;right:24px;bottom:18px;font-size:15px;color:var(--ink-3);text-align:center}
`;

function card({ skin, eyebrow, name, nat, lang, sigTitle, sigLine, facts, svg, cap }) {
  const h1 = name.length > 22 ? '64px' : name.length > 14 ? '78px' : '92px';
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><style>${FONTS}${TOKENS}${CSS}</style></head>
<body><div class="card" data-city="${esc(skin)}" style="--h1:${h1}">
<div class="l">
<p class="brand"><b>✦</b>cleo<span>sourced field guides</span></p>
<p class="eyebrow">${esc(eyebrow)}</p>
<h1>${esc(name)}</h1>${nat ? `<p class="nat"${lang ? ` lang="${lang}"` : ''}>${esc(nat)}</p>` : ''}
${sigTitle ? `<p class="sig"><b>★ ${esc(sigTitle)}</b>${esc(sigLine || '')}</p>` : '<p class="sig"></p>'}
<p class="facts">${facts}</p>
</div>
<div class="r">${svg || ''}<p class="cap">${esc(cap)}</p></div>
</div></body></html>`;
}

/** Every card to render: one per place page, one per live country hub. */
function jobs() {
  const guide = JSON.parse(rd('beta/data/guide.json')).pages;
  const countries = JSON.parse(rd('data/countries.json')).countries;
  const cname = Object.fromEntries(countries.map(c => [c.key, c.name]));
  const out = [], byCountry = {};
  for (const g of guide) {
    const f = g.key.replace(/\//g, '--'), d = JSON.parse(rd(`beta/data/places/${f}.json`)), st = d.stats;
    (byCountry[g.country] = byCountry[g.country] || []).push(d);
    const m = art.cityMap(d.name, d.places, d.colors || {}, { w: 470, h: 470, pad: 16, edges: false, scale: 1.5 });
    const sig = g.signature;
    out.push({ file: f + '.png', skin: d.key, name: d.name, nat: d.nat, lang: d.country === 'japan' ? 'ja' : '',
      eyebrow: `${cname[d.country] || ''} · field guide`.replace(/^ · /, ''),
      sigTitle: sig && sig.title, sigLine: sig && sig.line,
      facts: `<strong>${fmt(st.total)} places</strong> · ${fmt(st.sights)} sights · ${fmt(st.food)} to eat &amp; drink` +
        `<br>Every one traceable to the source that recommended it` +
        `<br>${st.lastChecked ? `Status checked ${esc(st.lastChecked)}` : 'Pinned and status-checked'}${st.closed ? ` · ${fmt(st.closed)} closed, kept for the record` : ''}`,
      svg: m && m.svg.replace(/<title[\s\S]*?<\/desc>/, ''), cap: m ? `${fmt(m.drawn - m.beyond)} verified pins, from the guide’s own coordinates${m.beyond ? ` · ${fmt(m.beyond)} outlying, off-frame` : ''}` : '' });
  }
  for (const c of countries.filter(c => c.live)) {
    const pages = byCountry[c.key] || []; if (!pages.length) continue;
    const pts = [], colors = {};
    for (const d of pages) for (const p of d.places) { const a = d.key + ':' + p.a; colors[a] = (d.colors || {})[p.a]; pts.push(Object.assign({}, p, { a })); }
    const m = art.cityMap(c.name, pts, colors, { w: 470, h: 470, pad: 16, edges: false, scale: 1.3 });
    const tot = pages.reduce((s, d) => s + d.stats.total, 0), closed = pages.reduce((s, d) => s + d.stats.closed, 0);
    const last = pages.map(d => d.stats.lastChecked).filter(Boolean).sort().pop();
    out.push({ file: `country-${c.key}.png`, skin: '', name: c.name, nat: null, eyebrow: `${pages.length} field guide${pages.length === 1 ? '' : 's'}`,
      sigTitle: null, sigLine: null,
      facts: `<strong>${fmt(tot)} places</strong> across ${pages.length} guide${pages.length === 1 ? '' : 's'}<br>Every one traceable to the source that recommended it` +
        `<br>${last ? `Status checked ${esc(last)}` : 'Pinned and status-checked'}${closed ? ` · ${fmt(closed)} closed, kept for the record` : ''}`,
      svg: m && m.svg.replace(/<title[\s\S]*?<\/desc>/, ''), cap: m ? `${fmt(m.drawn)} verified pins across every ${c.name} guide${m.beyond ? ` (${fmt(m.beyond)} off-frame)` : ''}` : '' });
  }
  return out;
}

(async () => {
  const only = new Set(process.argv.slice(2));
  const PW = loadPlaywright();
  if (!PW) { console.error('>>> SKIP — Playwright/Chromium not available; og:image keeps the shared assets/og-cover.png'); process.exit(0); }
  let browser;
  try { browser = await PW.chromium.launch(); } catch (e) { browser = await PW.chromium.launch({ executablePath: '/opt/pw-browsers/chromium' }); }
  const page = await browser.newPage({ viewport: { width: 1200, height: 630 }, deviceScaleFactor: 1 });
  await page.route('**/*', r => r.request().url().startsWith('data:') ? r.continue() : r.abort());   // nothing leaves the machine
  fs.mkdirSync(OUT, { recursive: true });
  let n = 0, big = [];
  for (const j of jobs()) {
    if (only.size && !only.has(j.file.replace(/\.png$/, '').replace(/--/g, '/'))) continue;
    await page.setContent(card(j), { waitUntil: 'load' });
    await page.evaluate(() => document.fonts.ready);
    const buf = await page.screenshot({ type: 'png', clip: { x: 0, y: 0, width: 1200, height: 630 } });
    fs.writeFileSync(path.join(OUT, j.file), buf); n++;
    if (buf.length > 300 * 1024) big.push(`${j.file} ${Math.round(buf.length / 1024)} KB`);
  }
  await browser.close();
  if (big.length) { console.error('>>> FAIL — over the 300 KB budget: ' + big.join(', ')); process.exit(1); }
  console.log(`>>> PASS — wrote ${n} share card(s) to beta/assets/og/ (1200×630, ≤ 300 KB). Run \`npm run beta\` to point og:image at them.`);
})();
